/**
 * Landing-page media: reels, loops, posters and stills under /assets/landing, with content-hashed
 * file names (the /assets cache is immutable for a year). Look assets up by their stable id, the
 * file's path without the hash, e.g. 'eu-ai-act/eu-ai-act-explainer-loop.mp4'.
 *
 * Generated by scripts/landing-media/build-manifest.mjs; provenance and approvals live in
 * scripts/landing-media/provenance.json, which is never bundled or served. See docs/landing-media.md.
 */
import manifest from './manifest.json'

export type LandingMediaKind = 'video-full' | 'video-loop' | 'poster' | 'image'

export type LandingMedia = {
  /** Stable id: path under /assets/landing without the content hash. */
  id: string
  /** Public URL path, content-hashed. */
  path: string
  kind: LandingMediaKind
  page: string
  slot: string
  captions?: string
  alt: string
  width: number
  height: number
  /** Seconds; null for images. */
  duration: number | null
  codecs: string
  bytes: number
  sha256: string
}

export const LANDING_MEDIA: readonly LandingMedia[] = manifest.assets as LandingMedia[]

const BY_ID = new Map(LANDING_MEDIA.map((a) => [a.id, a]))

/** The asset with this id; throws on an unknown id so a typo fails at build time, not as a 404. */
export function landingMedia(id: string): LandingMedia {
  const a = BY_ID.get(id)
  if (!a) throw new Error(`Unknown landing media id: ${id}`)
  return a
}

/** The public URL for an asset id. */
export function landingMediaSrc(id: string): string {
  return landingMedia(id).path
}

/**
 * A video with its sources (AV1 WebM first, H.264 MP4 fallback) and poster, by stem:
 * landingVideo('eu-ai-act/eu-ai-act-explainer-loop') or landingVideo('readiness/readiness-assessment-16x9').
 * Reel loops use '<reel>-loop-poster'; everything else uses '<stem>-poster'.
 */
export function landingVideo(stem: string): { mp4: LandingMedia; webm: LandingMedia; poster: LandingMedia } {
  const mp4 = landingMedia(`${stem}.mp4`)
  const webm = landingMedia(`${stem}.webm`)
  const poster = BY_ID.get(`${stem}-poster.webp`) ?? landingMedia(`${stem.replace(/-full$/, '')}-poster.webp`)
  return { mp4, webm, poster }
}

/** Every asset intended for a page, e.g. 'ai-build-sprint' or 'eu-ai-act-readiness'. */
export function landingMediaForPage(page: string): LandingMedia[] {
  return LANDING_MEDIA.filter((a) => a.page === page)
}
